// Spellslinger Duels - rules pack: 300 more commanders (2026-10-26, owner's request: "build more commanders ... maybe just build 300 of them").
// Wordings only; the engine pieces are in 15k-cmdr300.js. Uses the cl / clx / cmd / act / SPEC / selfCond helpers from rules/cmdr.js.
// Most-played commanders first (EDHREC rank), the ones with a single unread line before the ones with two.

// ===== Batch 1: combat damage, exile-and-cast, extra combats, counters =====
cl(/^Whenever ~ deals combat damage to a player, create a Treasure token and exile the top card of that player's library\. Until end of turn, you may cast that card\.$/, R => { R.trig.push({ ev: 'hitPlayer', effects: [cmd('ragavan')] }); });
cl(/^At the beginning of your end step, you may sacrifice an artifact, creature, enchantment, land, or planeswalker\. If you do, each opponent may sacrifice a permanent of their choice that shares a card type with it\. For each opponent who doesn't, that player loses 2 life and you draw a card\.$/, R => { R.trig.push({ ev: 'end', who: 'your', effects: [cmd('braids')] }); });
cl(/^Whenever one or more creatures you control each with power greater than its base power deals combat damage to a player, draw a card\.$/, R => { R.trig.push({ ev: 'combatHitAny', fn: 'kutzil', effects: [{ t: 'draw', n: 1 }] }); });
cl(/^\{1\}\{W\/P\}\{W\/P\}, Sacrifice two other artifacts and\/or creatures: Put an indestructible counter on ~\.$/, (R, m, ctx) => { act(R, ctx.line, '{1}{W}{W}', [cmd('indestructCounter')], a => { a.cost.sacOthers = 2; a.cost.sacAny = true; }); });
cl(/^\{G\/P\}\{G\/P\}, Sacrifice two other creatures: Put an indestructible counter on ~\.$/, (R, m, ctx) => { act(R, ctx.line, '{G}{G}', [cmd('indestructCounter')], a => { a.cost.sacOthers = 2; }); });
cl(/^\{5\}: Shuffle your library, then exile the top card\. Until end of turn, you may play that card without paying its mana cost\.$/, (R, m, ctx) => { act(R, ctx.line, '{5}', [cmd('urza5')]); });
cl(/^Whenever ~ attacks for the first time each turn, untap all creatures you control\. After this phase, there is an additional combat phase\.$/, R => { R.trig.push({ ev: 'attacks', fn: 'selfAttacks', once: 'aurelia', effects: [cmd('extraCombatUntap')] }); });
cl(/^Whenever you attack, if it's the first combat phase of the turn, untap all attacking creatures\. They gain first strike until end of turn\. After this phase, there is an additional combat phase\.$/, R => { R.trig.push({ ev: 'attacks', fn: 'anyAttackMine', cond: 'it is the first combat phase of the turn', once: 'karlach', effects: [cmd('karlach')] }); });
cl(/^Whenever you gain life, put a \+1\/\+1 counter on target creature or enchantment you control\.$/, R => { R.trig.push({ ev: 'gainLife', effects: [cmd('heliodCounter')] }); });
cl(/^Whenever you attack with one or more non-Gnome creatures, put a \+1\/\+1 counter on ~, then create X 1\/1 colorless Gnome artifact creature tokens that are tapped and attacking, where X is the number of \+1\/\+1 counters on ~\.$/, R => { R.trig.push({ ev: 'attacks', fn: 'nonGnomeAttack', effects: [cmd('animPakal')] }); });
cl(/^Discard three cards: Exile ~\. Return it to the battlefield tapped under its owner's control at the beginning of the next end step\.$/, (R, m, ctx) => { act(R, ctx.line, '{0}', [cmd('nezahal')], a => { a.cost.discard = 3; }); });
cl(/^Whenever you lose life, draw that many cards\.$/, R => { R.trig.push({ ev: 'loseLife', effects: [cmd('vilis')] }); });
cl(/^Whenever a commander you control deals combat damage to an opponent, it deals that much damage to each other opponent\.$/, R => { R.trig.push({ ev: 'hitPlayer', fn: 'cmdrHitsOpp', effects: [cmd('kediss')] }); });
cl(/^Whenever ~ deals combat damage to a player, create four 3\/3 blue Serpent creature tokens named ~'s Coil\.$/, R => { R.trig.push({ ev: 'hitPlayer', effects: [cmd('koma')] }); });
cl(/^When ~ dies, create X 1\/1 white Vampire creature tokens with lifelink, where X is ~'s power\.$/, R => { R.trig.push({ ev: 'dies', effects: [cmd('elenda')] }); });
cl(/^At the beginning of your end step, create a Treasure token for each creature that died this turn\.$/, R => { R.trig.push({ ev: 'end', who: 'your', effects: [cmd('mahadi')] }); });
cl(/^Whenever a Dragon you control attacks, it gains double strike until end of turn\.$/, R => { R.trig.push({ ev: 'attacks', fn: 'dragonAttacks', effects: [cmd('atarka')] }); });
cl(/^Whenever another nontoken Dragon you control enters, create a token that's a copy of it, except the token isn't legendary\.$/, R => { R.trig.push(SPEC('enters', { ctl: 'you', sub: 'Dragon', nontoken: true, another: true }, { effects: [cmd('miirym')] })); });
cl(/^Whenever ~ or another Dragon you control enters, create a Treasure token\.$/, R => { R.trig.push(SPEC('enters', { ctl: 'you', sub: 'Dragon' }, { effects: [{ t: 'artToken', kind: 'treasure', n: 1 }] })); });
cl(/^Whenever you sacrifice a permanent, put a \+1\/\+1 counter on ~\.$/, R => { R.trig.push({ ev: 'sacrificed', fn: 'mySacrifice', effects: [cmd('selfCounter')] }); });
cl(/^Whenever another creature you control enters, you gain life equal to that creature's toughness\.$/, R => { R.trig.push({ ev: 'enters', another: true, ctxTarget: true, effects: [cmd('trostani')] }); });
cl(/^Whenever ~ attacks, you gain 1 life for each attacking Elf you control\.$/, R => { R.trig.push({ ev: 'attacks', effects: [cmd('dwynen')] }); });
cl(/^Whenever a creature deals combat damage to one of your opponents, its controller may draw a card\.$/, R => { R.trig.push({ ev: 'hitPlayer', fn: 'edric', effects: [cmd('edric')] }); });
cl(/^Whenever ~ attacks, mill three cards\. Then you may return a land card from your graveyard to the battlefield tapped\.$/, R => { R.trig.push({ ev: 'attacks', effects: [{ t: 'millSelf', n: 3 }, cmd('teval')] }); });
cl(/^Whenever an opponent casts a spell, ~ deals damage equal to that spell's mana value to any target\.$/, R => { R.trig.push({ ev: 'cast', filter: 'any', who: 'opp', effects: [cmd('kaervek', { target: 'any', good: false })] }); });
cl(/^At the beginning of your upkeep, if an opponent is the monarch, create a 1\/1 black Assassin creature token with deathtouch and haste\.$/, R => { R.trig.push({ ev: 'upkeep', who: 'your', cond: 'an opponent is the monarch', effects: [{ t: 'token', n: 1, p: 1, q: 1, name: 'black Assassin', kw: ['deathtouch', 'haste'] }] }); });
cl(/^Whenever ~ attacks, double the power of each Dragon you control until end of turn\.$/, R => { R.trig.push({ ev: 'attacks', effects: [cmd('thrakkus')] }); });
cl(/^Whenever a creature you control with deathtouch deals combat damage to a player, that player gets two poison counters\.$/, R => { R.trig.push({ ev: 'hitPlayer', fn: 'deathtouchHit', effects: [cmd('fynn')] }); });
cl(/^Whenever a creature you control that's enchanted or equipped attacks, that creature gains double strike until end of turn\.$/, R => { R.trig.push({ ev: 'attacks', fn: 'modifiedAttack', effects: [cmd('reyav')] }); });
cl(/^Whenever you cast a legendary spell, draw a card\. This ability triggers only once each turn\.$/, R => { R.trig.push(SPEC('cast', { ctl: 'you', legendary: true }, { once: 'venat', effects: [{ t: 'draw', n: 1 }] })); });
cl(/^Whenever you cast a noncreature spell with mana value 3 or greater, draw a card\.$/, R => { R.trig.push(SPEC('cast', { ctl: 'you', noncreature: true, mvMin: 3 }, { effects: [{ t: 'draw', n: 1 }] })); });
cl(/^Whenever ~ attacks, it deals X damage to each opponent and you gain X life, where X is the number of creatures you control with power 2 or less\.$/, R => { R.trig.push({ ev: 'attacks', effects: [cmd('arabella')] }); });

// ===== Batch 2: taxes, cost cuts, draws and small engines =====
cl(/^Whenever another nontoken creature you control dies, return that card to its owner's hand at the beginning of the next end step\.$/, R => { R.trig.push({ ev: 'creatureDies', another: true, mine: true, nontoken: true, effects: [cmd('liesa')] }); });
cl(/^If an opponent would mill one or more cards, they mill twice that many cards instead\.$/, R => { R.millDouble = true; });
cl(/^When ~ dies, put X \+1\/\+1 counters on each legendary creature you control, where X is the number of \+1\/\+1 counters on ~\.$/, R => { R.trig.push({ ev: 'dies', effects: [cmd('aerithDies')] }); });
cl(/^\{T\}: Each player may draw a card, then each player who drew a card this way gains 1 life\.$/, (R, m, ctx) => { act(R, ctx.line, '{T}', [cmd('kwain')]); });
cl(/^Whenever a source you control deals noncombat damage to an opponent, you draw that many cards\.$/, R => { R.trig.push({ ev: 'playerDamaged', fn: 'nivDamage', effects: [cmd('drawCtx')] }); });
cl(/^Whenever an opponent loses life for the first time during each of their turns, put a \+1\/\+1 counter on ~ and draw a card\.$/, R => { R.trig.push({ ev: 'loseLife', fn: 'oppFirstLoss', effects: [cmd('selfCounter'), { t: 'draw', n: 1 }] }); });
cl(/^Noncreature spells cost \{1\} more to cast\.$/, R => { R.spellTax = { who: 'all', what: 'noncreature', n: 1 }; });
cl(/^Spells your opponents cast cost \{1\} more to cast\.$/, R => { R.spellTax = { who: 'opp', what: 'any', n: 1 }; });
cl(/^Spells your opponents cast that target one or more commanders you control cost \{3\} more to cast\.$/, R => { R.spellTax = { who: 'opp', what: 'targetsMyCommander', n: 3 }; });
cl(/^Creature spells you cast cost \{1\} less to cast for each \+1\/\+1 counter on ~\.$/, R => { R.reducer = { what: 'Creature', minPow: 0, n: 1, perCounter: true }; });
cl(/^When you cast ~, you may return target Angel or Human creature card from your graveyard to the battlefield\.$/, R => { R.castTrig = [cmd('bruna')]; });
cl(/^Whenever you draw your fifth card each turn, ~ and Drakes you control each get \+X\/\+X until end of turn, where X is the number of cards in your hand\.$/, R => { R.trig.push({ ev: 'draw', nth: 5, effects: [cmd('alandra')] }); });
cl(/^\{T\}, Sacrifice a Treasure: Goad target creature\.$/, (R, m, ctx) => { act(R, ctx.line, '{T}, Sacrifice a Treasure', [cmd('goadTarget', { target: 'creature', theirs: true, good: false })]); });
cl(/^\{4\}: Scry 1, then reveal the top card of your library\. If it's a land card, put it onto the battlefield tapped\. Otherwise, draw a card\.$/, (R, m, ctx) => { act(R, ctx.line, '{4}', [cmd('thrasios')]); });
cl(/^Spells you cast with mana value 6 or greater have cascade\.$/, R => { R.trig.push(SPEC('cast', { ctl: 'you', mvMin: 6 }, { effects: [cmd('cascadeCast')] })); });
cl(/^Whenever you cast a spell from anywhere other than your hand, draw a card\.$/, R => { R.trig.push({ ev: 'cast', fn: 'castNotFromHand', filter: 'any', effects: [{ t: 'draw', n: 1 }] }); });
cl(/^All Rats have fear\.$/, R => { R.statics.push({ other: false, type: 'Rat', p: 0, q: 0, kw: ['fear'], global: true }); });
cl(/^At the beginning of your end step, if creatures you control have total toughness 10 or greater, draw a card\. Then if creatures you control have total toughness 20 or greater, untap each creature you control\. Then if creatures you control have total toughness 40 or greater, each opponent loses half their life, rounded up\.$/, R => { R.trig.push({ ev: 'end', who: 'your', effects: [cmd('betor')] }); });
cl(/^As long as you've cast two or more noncreature spells this turn, ~ has double strike\.$/, R => { selfCond(R, { cond: "you've cast two or more noncreature spells this turn", p: 0, q: 0, kw: ['double strike'] }); });
cl(/^Spells you cast with mana value 5 or greater cost \{1\} less to cast and can't be countered\.$/, R => { R.reducer = { what: 'mv5', n: 1 }; R.spellsUncounterable = 'mv5'; });
cl(/^Whenever another legendary creature you control enters, put a \+1\/\+1 counter on ~\.$/, R => { R.trig.push(SPEC('enters', { ctl: 'you', type: 'Creature', legendary: true, another: true }, { effects: [cmd('selfCounter')] })); });
cl(/^Whenever a creature token you control leaves the battlefield, draw a card if it was attacking\. Otherwise, each opponent loses 1 life\.$/, R => { R.trig.push({ ev: 'leaves', fn: 'zurgoLeaves', anyLeave: true, effects: [cmd('zurgo')] }); });
cl(/^Whenever another creature you own dies, return it to your hand unless target opponent pays 3 life\.$/, R => { R.trig.push({ ev: 'creatureDies', fn: 'ownedCreatureDies', effects: [cmd('athreos', { target: 'player', theirs: true, good: false })] }); });
cl(/^Whenever a player mills one or more creature cards, you create a 1\/1 black Horror creature token\.$/, R => { R.trig.push({ ev: 'milled', fn: 'milledCreature', effects: [{ t: 'token', n: 1, p: 1, q: 1, name: 'black Horror', kw: [] }] }); });
cl(/^Whenever ~ attacks, return up to one target permanent card with mana value less than or equal to ~'s power from your graveyard to the battlefield\.$/, R => { R.trig.push({ ev: 'attacks', effects: [cmd('carmen')] }); });
cl(/^Other artifact creatures you control have flying, trample, indestructible, and haste\.$/, R => { R.statics.push({ other: true, type: 'Artifact', p: 0, q: 0, kw: ['flying', 'trample', 'indestructible', 'haste'] }); });
cl(/^When ~ enters, return target enchantment card that isn't a God from your graveyard to your hand\.$/, R => { R.etb.push(cmd('heliodRadiant')); });
cl(/^\{G\}\{U\}, \{T\}: Double the number of each kind of counter on up to two target creatures and\/or artifacts you control\.$/, (R, m, ctx) => { act(R, ctx.line, '{G}{U}, {T}', [cmd('doubleCountersMany', { n: 2, kinds: 'creatureOrArtifact' })]); });
cl(/^\{G\}\{U\}, \{T\}: Double the number of each kind of counter on target artifact, creature, or land\.$/, (R, m, ctx) => { act(R, ctx.line, '{G}{U}, {T}', [cmd('doubleCountersMany', { n: 1, kinds: 'any' })]); });
cl(/^At the beginning of each opponent's upkeep, ~ deals 2 damage to that player unless they sacrifice a creature of their choice\.$/, R => { R.trig.push({ ev: 'upkeep', who: 'opp', effects: [cmd('mogis')] }); });

// ===== Batch 3: doublers, top-of-library casts, impulse, token makers, small triggers =====
cl(/^If a creature dying causes a triggered ability of a permanent you control to trigger, that ability triggers an additional time\.$/, R => { R.doubleDeath = true; });
cl(/^If a creature attacking causes a triggered ability of a permanent you control to trigger, that ability triggers an additional time\.$/, R => { R.doubleAttackAny = true; });
cl(/^If a creature you control attacking causes a triggered ability of a permanent you control to trigger, that ability triggers an additional time\.$/, R => { R.doubleAttackAny = true; });
cl(/^If a creature you control dealing combat damage to a player causes a triggered ability of a permanent you control to trigger, that ability triggers an additional time\.$/, R => { R.doubleHit = true; });
cl(/^If a triggered ability of an Ally you control triggers, that ability triggers an additional time\.$/, R => { R.doubleAlly = true; });
cl(/^If a permanent entering causes a triggered ability of a permanent you control to trigger, that ability triggers an additional time\.$/, R => { R.doubleEnter = true; });
cl(/^\{1\}\{B\}, \{T\}, Sacrifice another creature: Draw X cards, where X is that creature's power\.$/, (R, m, ctx) => { act(R, ctx.line, '{1}{B}, {T}', [cmd('drawSacPow')], a => { a.cost.sacPerm = 'another creature'; }); });
cl(/^Whenever you gain life, put that many \+1\/\+1 counters on target Halfling or Treefolk\.$/, R => { R.trig.push({ ev: 'gainLife', effects: [cmd('treebeard')] }); });
cl(/^Whenever you cast a legendary spell, untap ~\.$/, R => { R.trig.push(SPEC('cast', { ctl: 'you', legendary: true }, { effects: [cmd('untapSelf')] })); });
cl(/^Whenever one or more creature cards are put into your graveyard from your library, create a 2\/2 black Zombie creature token\.$/, R => { R.trig.push({ ev: 'milled', fn: 'myMilledCreature', effects: [{ t: 'token', n: 1, p: 2, q: 2, name: 'black Zombie', kw: [] }] }); });
cl(/^When ~ enters, reveal the top ten cards of your library\. For each card type, you may put a card of that type from among the revealed cards into your hand\. Put the rest on the bottom of your library in a random order\.$/, R => { R.etb.push(cmd('atraxaGU')); });
cl(/^Whenever ~ attacks, if there are seven or more cards in your graveyard, you may create Scion of the Deep, a legendary 8\/8 blue Octopus creature token\.$/, R => { R.trig.push({ ev: 'attacks', cond: 'you have seven or more cards in your graveyard', effects: [cmd('kioraScion')] }); });
cl(/^Whenever ~ attacks, each opponent loses X life, where X is the number of other attacking creatures\.$/, R => { R.trig.push({ ev: 'attacks', effects: [cmd('severina')] }); });
cl(/^Whenever another creature you control dies, draw a card if it was attacking\. Otherwise, ~ deals 1 damage to each opponent\.$/, R => { R.trig.push({ ev: 'creatureDies', fn: 'myCreatureDiesAtk', effects: [cmd('garna')] }); });
cl(/^Whenever one or more cards leave your graveyard, create a tapped 2\/2 black Zombie creature token\.$/, R => { R.trig.push({ ev: 'gyLeave', effects: [{ t: 'token', n: 1, p: 2, q: 2, name: 'black Zombie', kw: [], tapped: true }] }); });
cl(/^Enchantment spells you cast from your hand have cascade\.$/, R => { R.trig.push({ ev: 'cast', fn: 'castEnchantFromHand', filter: 'any', effects: [cmd('cascadeCast')] }); });
cl(/^Whenever ~ or another nontoken Cat you control enters, create a 1\/1 white Cat creature token\.$/, R => { R.trig.push(SPEC('enters', { ctl: 'you', sub: 'Cat', nontoken: true }, { effects: [{ t: 'token', n: 1, p: 1, q: 1, name: 'white Cat', kw: [] }] })); });
cl(/^At the beginning of each player's upkeep, that player loses 2 life and draws two cards\.$/, R => { R.trig.push({ ev: 'upkeep', who: 'each', effects: [cmd('seizan')] }); });
cl(/^\{3\}\{W\}\{W\}: Attacking creatures you control get \+X\/\+X until end of turn, where X is the number of attacking creatures\.$/, (R, m, ctx) => { act(R, ctx.line, '{3}{W}{W}', [cmd('jazal')]); });
cl(/^Whenever a creature you control deals combat damage to a player, you gain life equal to that creature's toughness\.$/, R => { R.trig.push({ ev: 'hitPlayer', fn: 'myCreatureHit', effects: [cmd('ikra')] }); });
cl(/^You may cast Dragon spells from the top of your library\.$/, R => { R.castTopCreatures = { when: o => hasType(o, 'Dragon') }; });
cl(/^You may cast Ally spells from the top of your library\.$/, R => { R.castTopCreatures = { when: o => hasType(o, 'Ally') }; });
cl(/^You may cast Angel spells and Human spells from the top of your library\.$/, R => { R.castTopCreatures = { when: o => hasType(o, 'Angel') || hasType(o, 'Human') }; });
cl(/^\{W\}\{B\}, Remove six \+1\/\+1 counters from ~: Exile target creature\.$/, (R, m, ctx) => { act(R, ctx.line, '{W}{B}', parseEffects('Exile target creature.'), a => { a.cost.removeCounter = 6; }); });
cl(/^Whenever one or more nontoken Vampires you control attack, create a 1\/1 white Vampire creature token with lifelink\.$/, R => { R.trig.push({ ev: 'attacks', fn: 'nontokenVampireAttack', effects: [{ t: 'token', n: 1, p: 1, q: 1, name: 'white Vampire', kw: ['lifelink'] }] }); });
cl(/^At the beginning of each end step, if an opponent lost 3 or more life this turn, you may draw a card\.$/, R => { R.trig.push({ ev: 'end', who: 'each', fn: 'oppLost3', effects: [{ t: 'draw', n: 1 }] }); });
cl(/^~ creatures you control have indestructible\.$/, R => { R.statics.push({ other: false, type: 'Sliver', p: 0, q: 0, kw: ['indestructible'] }); });
cl(/^Whenever ~ deals combat damage to a player, for each token you control, create a 1\/1 white Rabbit creature token\.$/, R => { R.trig.push({ ev: 'hitPlayer', effects: [cmd('cadira')] }); });
cl(/^~ enters tapped and doesn't untap during your untap step\.$/, R => { R.entersTapped = true; R.kw.add('nountap'); });
cl(/^\{4\}, \{T\}, Sacrifice ~: Each opponent who lost life this turn sacrifices a creature with the greatest power among creatures they control\.$/, (R, m, ctx) => { act(R, ctx.line, '{4}, {T}', [cmd('papalymo')], a => { a.cost.sacSelf = true; }); });
cl(/^When ~ enters, reveal the top six cards of your library\. Put all Goblin creature cards with mana value 5 or less from among them onto the battlefield and the rest on the bottom of your library in a random order\.$/, R => { R.etb.push(cmd('muxus')); });
cl(/^Whenever ~ deals combat damage to an opponent, it deals that much damage to each other opponent if ~'s power is 7 or greater\.$/, R => { R.trig.push({ ev: 'hitPlayer', fn: 'selfHitsOpp', effects: [cmd('vincent')] }); });
cl(/^When ~ enters, create a Treasure token if an opponent controls more lands than you\. You gain 4 life if an opponent has more life than you\. Create two 1\/1 blue Fish creature tokens if an opponent controls more creatures than you\. Draw a card if an opponent has more cards in hand than you\.$/, R => { R.etb.push(cmd('beza')); });
cl(/^Whenever ~ attacks, up to one target creature can't block this turn\. If you're the monarch, creatures can't block this turn\.$/, R => { R.trig.push({ ev: 'attacks', effects: [cmd('aragorn', { target: 'creature', theirs: true, good: false, optional: true })] }); });
cl(/^Whenever one or more \+1\/\+1 counters are put on a creature you control, ~ deals that much damage to target opponent\.$/, R => { R.trig.push({ ev: 'counters', fn: 'counterOnMine', effects: [cmd('shalaiHallar', { target: 'player', theirs: true, good: false })] }); });
cl(/^Whenever a land enters, ~ deals 2 damage to that land's controller\.$/, R => { R.trig.push({ ev: 'landfall', fn: 'anyLand', effects: [cmd('zoZu')] }); });
cl(/^During your turn, ~ and other Knights you control have flying\.$/, R => { R.statics.push({ other: false, type: 'Knight', p: 0, q: 0, kw: ['flying'], cond: 'it is your turn' }); });
cl(/^At the beginning of each of your postcombat main phases, you may pay X life, where X is the number of opponents that were dealt combat damage this turn\. If you do, draw X cards\.$/, R => { R.trig.push({ ev: 'main2', fn: 'myMain2', effects: [cmd('tymna')] }); });
cl(/^If one or more creature tokens would be created under your control, those tokens plus a 1\/1 white Soldier creature token are created instead\.$/, R => { R.tokenPlusSoldier = true; });
cl(/^Whenever you cast a spell from exile or a land you control enters from exile, create a 2\/2 green Wolf creature token\.$/, R => { R.trig.push({ ev: 'playedFromExile', effects: [{ t: 'token', n: 1, p: 2, q: 2, name: 'green Wolf', kw: [] }] }); });
cl(/^At the beginning of your end step, if you gained life this turn, return up to one target creature card with mana value X or less from your graveyard to the battlefield, where X is the amount of life you gained this turn\.$/, R => { R.trig.push({ ev: 'end', who: 'your', fn: 'gainedLifeTurn', effects: [cmd('moseo')] }); });
cl(/^At the beginning of your end step, return target creature card with mana value X or less from your graveyard to the battlefield, where X is the amount of life you gained this turn\.$/, R => { R.trig.push({ ev: 'end', who: 'your', effects: [cmd('moseo')] }); });
cl(/^Sliver spells you cast have cascade\.$/, R => { R.trig.push(SPEC('cast', { ctl: 'you', sub: 'Sliver' }, { effects: [cmd('cascadeCast')] })); });
cl(/^Whenever you scry or surveil, draw a card\.$/, R => { R.trig.push({ ev: 'scry', effects: [{ t: 'draw', n: 1 }] }); });
cl(/^Whenever another legendary permanent you control enters, put a \+1\/\+1 counter on ~\.$/, R => { R.trig.push(SPEC('enters', { ctl: 'you', legendary: true, another: true }, { effects: [cmd('selfCounter')] })); });
cl(/^Whenever you cast a legendary spell, draw a card\.$/, R => { R.trig.push(SPEC('cast', { ctl: 'you', legendary: true }, { effects: [{ t: 'draw', n: 1 }] })); });
cl(/^Whenever you cast an Adventure or Dragon spell, ~ deals damage equal to that spell's mana value to any target that isn't a commander\.$/, R => { R.trig.push({ ev: 'cast', fn: 'adventureOrDragon', filter: 'any', effects: [cmd('lozhan', { target: 'any', good: false })] }); });
cl(/^Whenever an Illusion you control dies, you may put a permanent card with mana value less than or equal to that creature's power from your hand onto the battlefield\.$/, R => { R.trig.push({ ev: 'creatureDies', fn: 'myIllusionDies', effects: [cmd('minn')] }); });
cl(/^When ~ dies, gain control of target creature\.$/, R => { R.trig.push({ ev: 'dies', effects: [{ t: 'stealPerm', target: 'creature', good: false, theirs: true }] }); });
cl(/^Whenever one or more tokens you control enter, create a 1\/1 black Vampire Rogue creature token with lifelink\. This ability triggers only once each turn\.$/, R => { R.trig.push({ ev: 'creatureTokenMade', once: 'bertram', fn: 'myTokenMade', effects: [{ t: 'token', n: 1, p: 1, q: 1, name: 'black Vampire Rogue', kw: ['lifelink'] }] }); });
cl(/^Each other non-Human creature you control enters with an additional \+1\/\+1 counter on it\.$/, R => { R.entersCounterOthers = { not: 'Human' }; });
cl(/^\{6\}: Create a token that's a copy of target artifact you control, except it's a 1\/1 Soldier creature in addition to its other types\.$/, (R, m, ctx) => { act(R, ctx.line, '{6}', [cmd('urzaKroog')]); });
